components.css:
@import url('https://fonts.googleapis.com/css2?family=Anton&display=swap');
.ds-cta-primary{display:inline-flex;align-items:center;justify-content:center;background:linear-gradient(135deg,#00e676,#00c853);color:#030504;font-family:'Anton',sans-serif;font-size:1rem;letter-spacing:.04em;text-transform:uppercase;text-decoration:none;padding:14px 28px;border-radius:6px;box-shadow:0 24px 64px rgba(0,230,118,.28);transition:transform .2s ease,box-shadow .2s ease}
.ds-cta-primary:hover{transform:translateY(-2px);box-shadow:0 28px 72px rgba(0,230,118,.38)}
.ds-cta-primary:focus-visible{outline:3px solid rgba(0,200,83,.72);outline-offset:3px}
